const input = $input.first().json.body || $input.first().json;
const rides = Array.isArray(input.rides) ? input.rides.slice(0, 100).map((r, i) => ({ ref: r.ref || `ride-${i + 1}`, originArea: r.originArea, destinationArea: r.destinationArea, departureTime: r.departureTime, availableSeats: Number(r.availableSeats || 0), pricePerSeat: r.pricePerSeat == null ? null : Number(r.pricePerSeat), serviceType: r.serviceType, accessibility: r.accessibility, routeFlexibility: r.routeFlexibility })) : [];
const request = { originArea: input.request?.originArea, destinationArea: input.request?.destinationArea, departureWindow: input.request?.departureWindow, seatsNeeded: Number(input.request?.seatsNeeded || 1), budgetPerSeat: input.request?.budgetPerSeat == null ? null : Number(input.request.budgetPerSeat), preferences: input.request?.preferences || [] };
const prompt = `Rank potential shared-ride options using only coarse area, time window, seat capacity, price and stated preferences. Do not claim identity verification or safety, infer protected traits, reveal contact details or exact addresses, or make bookings. Return JSON matches [{ref,fitReason,tradeoffs}], noMatchReason (string), caveats (array). Safety and pickup details must be confirmed through the app by the users.
REQUEST=${JSON.stringify(request)}
RIDES=${JSON.stringify(rides)}`;
return [{ json: { prompt } }];

const response = $input.first().json;
let result; try { result = JSON.parse(response.candidates[0].content.parts[0].text); } catch { result = { matches: [], noMatchReason: 'Unable to rank options; search available rides directly.', caveats: [] }; }
return [{ json: { status: 'matches_ready', result, bookingCreated: false, requiresUserConfirmation: true } }];
